from PIL import Image,ImageDraw
import numpy as np
from scipy import ndimage as ndi
from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import dijkstra
im=np.array(Image.open('/app/target.png').convert('RGB')); mask=im.mean(2)<80
a=mask.copy()
for it in range(80):
 ch=False
 for st in (0,1):
  p=np.pad(a,1); n=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]
  B=np.sum(np.stack(n).astype(np.uint8),axis=0);A=sum((~n[k]&n[(k+1)%8]).astype(np.uint8) for k in range(8))
  c=((n[0]*n[2]*n[4]==0)&(n[2]*n[4]*n[6]==0)) if st==0 else ((n[0]*n[2]*n[6]==0)&(n[0]*n[4]*n[6]==0))
  rem=a&(B>=2)&(B<=6)&(A==1)&c
  if rem.any(): a[rem]=0;ch=True
 if not ch:break
ys,xs=np.where(a);coords=list(zip(xs.tolist(),ys.tolist()));idx={p:i for i,p in enumerate(coords)}
rr=[];cc=[];ww=[]
for i,(x,y) in enumerate(coords):
 for dx in (-1,0,1):
  for dy in (-1,0,1):
   if not(dx or dy):continue
   j=idx.get((x+dx,y+dy))
   if j is not None:rr.append(i);cc.append(j);ww.append(np.hypot(dx,dy))
G=csr_matrix((ww,(rr,cc)),shape=(len(coords),len(coords)))

def near(p):
 arr=np.array(coords);dd=((arr-np.array(p))**2).sum(1);return int(dd.argmin())
def path(pa,pb):
 ia,ib=near(pa),near(pb);dist,pre=dijkstra(G,directed=True,indices=ia,return_predecessors=True)
 j=ib;route=[j]
 while j!=ia:
  j=int(pre[j]);
  if j<0:raise RuntimeError('no path')
  route.append(j)
 return [coords[k] for k in route[::-1]]
def chain(points):
 out=[]
 for a0,b0 in zip(points,points[1:]):
  p=path(a0,b0);out.extend(p if not out else p[1:])
 return out
paths=[('red',path((438,251),(482,305))),('green',path((399,317),(416,314))),('blue',path((386,401),(642,446))),('yellow',path((271,535),(298,685))),('magenta',chain([(420,698),(460,758),(426,755),(408,725)])),('cyan',path((475,523),(746,687)))]
colors={'red':'red','green':'lime','blue':'#0099ff','yellow':'yellow','magenta':'magenta','cyan':'cyan'}
# decimate path by 8-pixel distance for readable coordinate output
for name,pts in paths:
 sm=[pts[0]];last=np.array(pts[0],float)
 for p in pts[1:]:
  if np.linalg.norm(np.array(p)-last)>=8:sm.append(p);last=np.array(p,float)
 if pts[-1]!=sm[-1]:sm.append(pts[-1])
 print(name,'len',len(pts),'simplified',sm)
out=Image.fromarray(im);dr=ImageDraw.Draw(out)
for name,pts in paths:
 dr.line(pts,fill=colors[name],width=3,joint='curve')
out.save('/app/output/skeleton_paths.png')
